/**
 * Every event the frontends emit, by name, with its attributes (ADR 0036).
 *
 * An event that is not in the tracking plan does not compile. Each one carries
 * the question it answers and the decision its value would change.
 */
export interface TrackedEvents {
  /**
   * A browser agent called one of the shop's WebMCP tools. Emitted with actor `webmcp`.
   *
   * WebMCP: Do browser agents use the shop's WebMCP tools, which ones, and do they succeed?
   * Decides: Which tools to keep, extend or drop; a high share of refusals means a tool's contract is wrong for an agent.
   */
  readonly webmcp_tool_invoked: {
    /** The tool's registered name; never its arguments. */
    readonly tool: string;
    /** Refused is the shop saying no; failed is the tool breaking. */
    readonly outcome: 'answered' | 'refused' | 'failed';
  };

  /**
   * A shopper opened a product page. Only with analytics consent.
   *
   * Product page: How do shoppers reach a product — a search, a category, the home page — and how many product views does a cart follow?
   * Decides: Where discovery work goes: the search box, the taxonomy or the home page's rows.
   */
  readonly product_viewed: {
    /** The page before this one, by kind; direct when there was none in this tab. */
    readonly arrived_from: 'search' | 'category' | 'home' | 'other' | 'direct';
  };

  /**
   * A shopper opened a category listing (R-0 of the redesign). Only with analytics consent.
   *
   * Browsing by category: Do people browse the taxonomy, or go straight to search?
   * Decides: Whether the category pages earn their place in the navigation.
   */
  readonly category_opened: {
    /** How the shopper got there: menu once the storefront has one (R-5), otherwise the kind of page before this one; direct when there was none in this tab. The kind and never the URL. */
    readonly arrived_from: 'menu' | 'search' | 'category' | 'home' | 'other' | 'direct';
  };

  /**
   * A shopper opened the words behind a spec — the quote and its support. Only with analytics consent.
   *
   * Specs with their source: Do shoppers open the sentence behind a spec, and do they compare products side by side once they can?
   * Decides: If nobody opens a source, the chip is decoration: keep the table, drop the chip's weight and spend review effort elsewhere. If comparisons are made and followed by a cart, the typed half of claims is worth its model and the next source (manuals, datasheets) is worth adding; if they are not, the comparison goes back to being a nice-to-have.
   */
  readonly spec_source_opened: {
    /** Where the value came from; only a value an approved claim put there has words to open. */
    readonly source: 'description';
  };

  /**
   * A shopper opened a side-by-side comparison. Only with analytics consent.
   *
   * Specs with their source: Do shoppers open the sentence behind a spec, and do they compare products side by side once they can?
   * Decides: If nobody opens a source, the chip is decoration: keep the table, drop the chip's weight and spend review effort elsewhere. If comparisons are made and followed by a cart, the typed half of claims is worth its model and the next source (manuals, datasheets) is worth adding; if they are not, the comparison goes back to being a nice-to-have.
   */
  readonly products_compared: {
    /** How many products were compared, two to four. */
    readonly products: number;
  };
}

/**
 * Which events wait for analytics consent. A behavioural event says what a
 * person did and is dropped until they agree; a technical one is not.
 */
export const TRACKED_EVENT_CONSENT: Readonly<Record<keyof TrackedEvents, 'behavioural' | 'technical'>> = {
  webmcp_tool_invoked: 'behavioural',
  product_viewed: 'behavioural',
  category_opened: 'behavioural',
  spec_source_opened: 'behavioural',
  products_compared: 'behavioural',
};
